package cli

import (
	"fmt"
	"strings"
)

func renderWhyStatic(blocks []whyBlock) string {
	var sb strings.Builder

	for i, block := range blocks {
		if i > 0 {
			sb.WriteString("\n")
		}

		fmt.Fprintf(&sb, "Lines %s\n", block.RangeText())

		if block.Commit.ShortHash != "" {
			fmt.Fprintf(&sb, "Commit: %s\n", block.Commit.ShortHash)
		}
		if block.Commit.Author != "" {
			fmt.Fprintf(&sb, "Author: %s\n", block.Commit.Author)
		}
		if block.Commit.WhenText != "" {
			fmt.Fprintf(&sb, "When: %s\n", block.Commit.WhenText)
		}
		if block.Commit.Subject != "" {
			fmt.Fprintf(&sb, "Subject: %s\n", block.Commit.Subject)
		}

		if block.Entire != nil {
			if block.Entire.CheckpointID != "" {
				fmt.Fprintf(&sb, "Entire Checkpoint: %s\n", block.Entire.CheckpointID)
			}
			if block.Entire.Agent != "" {
				fmt.Fprintf(&sb, "Entire Agent: %s\n", block.Entire.Agent)
			}
			if block.Entire.Summary != "" {
				fmt.Fprintf(&sb, "Entire Summary: %s\n", block.Entire.Summary)
			}
		}

		if len(block.CodeLines) > 0 {
			sb.WriteString("Code:\n")
			for _, line := range block.CodeLines {
				fmt.Fprintf(&sb, "  %s\n", line)
			}
		}
	}

	return sb.String()
}

