    99	func parseWhyBlamePorcelain(r io.Reader) ([]whyBlock, error) {
   100		scanner := bufio.NewScanner(r)
   101		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
   102		var (
   103			blocks []whyBlock
   104			cur    *whyBlameHeader
   105		)
   106	
   107		flush := func() error {
   108			if cur == nil {
   109				return nil
   110			}
   111			if !cur.ContentSeen {
   112				return fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
   113			}
   114	
   115			block := whyBlock{
   116				StartLine: cur.EndLine,
   117				EndLine:   cur.EndLine,
   118				Commit:    cur.Meta,
   119				CodeLines: []string{cur.LineText},
   120				Detail:    whyDetailCommit,
   121			}
   122	
   123			if len(blocks) > 0 {
   124				last := &blocks[len(blocks)-1]
   125				if last.Commit.Hash == block.Commit.Hash && last.EndLine+1 == block.StartLine {
   126					last.EndLine = block.EndLine
   127					last.CodeLines = append(last.CodeLines, block.CodeLines...)
   128					return nil
   129				}
   130			}
   131	
   132			blocks = append(blocks, block)
   133			return nil
   134		}
   135	
   136		for scanner.Scan() {
   137			line := scanner.Text()
   138			if strings.HasPrefix(line, "\t") {
   139				if cur == nil {
   140					return nil, fmt.Errorf("unexpected content line without header: %q", line)
   141				}
   142				cur.LineText = strings.TrimPrefix(line, "\t")
   143				cur.ContentSeen = true
   144				if err := flush(); err != nil {
   145					return nil, err
   146				}
   147				cur = nil
   148				continue
   149			}
   150	
   151			if strings.TrimSpace(line) == "" {
   152				continue
   153			}
   154	
   155			fields := strings.Fields(line)
   156			if len(fields) >= 3 && isHexCommitHash(fields[0]) {
   157				if err := flush(); err != nil {
   158					return nil, err
   159				}
   160	
   161				endLine, err := strconv.Atoi(fields[2])
   162				if err != nil {
   163					return nil, fmt.Errorf("invalid blame line number %q: %w", fields[2], err)
   164				}
   165	
   166				cur = &whyBlameHeader{
   167					Hash:    fields[0],
   168					EndLine: endLine,
   169					Meta: whyCommitInfo{
   170						Hash:      fields[0],
   171						ShortHash: shortCommitHash(fields[0]),
   172					},
   173				}
   174				continue
   175			}
   176	
   177			if cur == nil {
   178				return nil, fmt.Errorf("unexpected blame metadata without header: %q", line)
   179			}
   180	
   181			if strings.HasPrefix(line, "author ") {
   182				cur.Meta.Author = strings.TrimPrefix(line, "author ")
   183				continue
   184			}
   185			if strings.HasPrefix(line, "summary ") {
   186				cur.Meta.Subject = strings.TrimPrefix(line, "summary ")
   187				continue
   188			}
   189		}
   190	
   191		if err := scanner.Err(); err != nil {
   192			return nil, err
   193		}
   194		if cur != nil {
   195			if !cur.ContentSeen {
   196				return nil, fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
   197			}
   198			if err := flush(); err != nil {
   199				return nil, err
   200			}
   201		}
   202	
   203		return blocks, nil
   204	}
   205	
   206	type whyBlameHeader struct {
   207		Hash        string
   208		EndLine     int
   209		Meta        whyCommitInfo
   210		LineText    string
   211		ContentSeen bool
   212	}
