   214	func shortCommitHash(hash string) string {
   215		if len(hash) <= 10 {
   216			return hash
   217		}
   218		return hash[:10]
   219	}
   220	
   221	func isHexCommitHash(hash string) bool {
   222		if len(hash) == 0 {
   223			return false
   224		}
   225		for _, r := range hash {
   226			switch {
   227			case r >= '0' && r <= '9':
   228			case r >= 'a' && r <= 'f':
   229			case r >= 'A' && r <= 'F':
   230			default:
   231				return false
   232			}
   233		}
   234		return true
   235	}

